import{_ as e,c as o,o as s,ag as r}from"./chunks/framework.Cycwnjj0.js";const n="/assets/add-classic-editor-block-in-a-post.CmrYxuV_.webp",a="/assets/add-media-option-from-the-classic-editor.dP_S4wwm.webp",i="/assets/search-bar.Cwg-i0VN.webp",c="/assets/product-elements.D2iO6b6w.webp",l="/assets/text-link.Dx-y59-I.webp",d="/assets/product-image-link.KODS_bqk.webp",p="/assets/cta-link.ECWxrmeT.webp",g="/assets/feature-box.2X8mrtPT.webp",u="/assets/preview-of-customized-elements-of-a-specific-product.FbcgnQPn.webp",_=JSON.parse('{"title":"Product Elements","description":"","frontmatter":{},"headers":[],"relativePath":"guide/available-products-templates/product-elements.md","filePath":"guide/available-products-templates/product-elements.md"}'),h={name:"guide/available-products-templates/product-elements.md"};function m(f,t,b,w,k,y){return s(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="product-elements" tabindex="-1">Product Elements <a class="header-anchor" href="#product-elements" aria-label="Permalink to &quot;Product Elements&quot;">​</a></h1><p>AzonPress offers an advanced feature to <strong>display Amazon products</strong> using the <strong>WordPress Classic Editor</strong>. This article guides you through using the <strong>Product Elements</strong> of <strong>AzonPress</strong> in the <strong>Classic Editor</strong> of <strong>WordPress</strong>.</p><h2 id="product-elements-of-azonpress" tabindex="-1">Product Elements of AzonPress <a class="header-anchor" href="#product-elements-of-azonpress" aria-label="Permalink to &quot;Product Elements of AzonPress&quot;">​</a></h2><p>You can use the Product Elements to easily inform your consumers about your products. It is one of the important features so that a consumer can easily understand any product by using less time.</p><p>To learn how to use Product Elements options, follow the steps with the screenshots below –</p><p>First, add the <strong>Classic Editor</strong> block on your desired <strong>Page/Post</strong> (e.g., I have added the classic editor to a new post).</p><p>Now, to add the <strong>Classic Editor</strong>, click the Gutenberg editor&#39;s <strong>Plus (+) icon</strong>.</p><p><img src="'+n+'" alt="Add Classic editor block in a post"></p><p>Next, click the <strong>Add Media</strong> option from the classic editor bar, and a pop-up window appears with a couple of options.</p><p><img src="'+a+'" alt="Add media option from the classic editor"></p><p>Now, press <strong>AzonPress</strong> from the left sidebar and you will get <strong>Product Elements</strong> tabs.</p><p>Here, you will get a <strong>Search Bar</strong> option form where you can get the <strong>Settings</strong> options of the products that you have searched through the search bar.</p><p><img src="'+i+'" alt="Search Bar"></p><p>Now, enter the name of the products you want to change elements and click the <strong>Search</strong> button.</p><p>Once you search for your desired products, they will appear with <strong>Four</strong> major <strong>Settings</strong> options for showcasing your Amazon products. These are:</p><ul><li><strong>Text Link</strong></li><li><strong>Product Image Link</strong></li><li><strong>CTA Link</strong></li><li><strong>Feature Box</strong></li></ul><p><img src="'+c+'" alt="Product Elements"></p><p><strong>A detailed explanation of the Settings options mentioned above is given below:</strong></p><h3 id="text-link" tabindex="-1">Text Link <a class="header-anchor" href="#text-link" aria-label="Permalink to &quot;Text Link&quot;">​</a></h3><p>Here, you will get three options to customize the elements of desired products. These are:</p><ul><li><strong>Link Text</strong>: In this option, you can change the <strong>Title</strong> of the link.</li><li><strong>Open in New Window</strong>: If you want to open any product in a new window, keep the <strong>Yes</strong> checkbox enabled. Otherwise, click the <strong>No</strong> checkbox if you don&#39;t want it.</li><li><strong>Use No Follow Link</strong>: If you want to make your link a no follow link, keep the <strong>Yes</strong> checkbox enabled. Otherwise, click the <strong>No</strong> checkbox if you don&#39;t want it.</li></ul><p>Once you finish, click the <strong>Insert Text Link</strong> button and the changes will added to your desired <strong>Post/Page</strong>.</p><p><img src="'+l+'" alt="Text Link"></p><h3 id="product-image-link" tabindex="-1">Product Image Link <a class="header-anchor" href="#product-image-link" aria-label="Permalink to &quot;Product Image Link&quot;">​</a></h3><p>With this option, you can <strong>change the size</strong> (Small, Medium, or Large) <strong>of</strong> your desired <strong>product image</strong> by clicking the <strong>Insert small, Insert medium,</strong> or <strong>Insert large</strong> button.</p><p><img src="'+d+'" alt="Product Image Link"></p><h3 id="cta-link" tabindex="-1">CTA Link <a class="header-anchor" href="#cta-link" aria-label="Permalink to &quot;CTA Link&quot;">​</a></h3><p>Using this option, you <strong>can change</strong> the <strong>Buy Now</strong> (purchase) <strong>Button</strong> of your desired products.</p><p>Here, you will find the <strong>different templates</strong> for the purchase button under <strong>Button Style</strong>.</p><p>Now, to add the button either as a <strong>Product Details Button</strong> or <strong>Add To Cart Button</strong> into your product, you can choose any template as per your wish simply by clicking the <strong>Insert</strong> button. Your selected button will be added to your desired <strong>Post/Page</strong>.</p><p>But for the <strong>Custom Button</strong>, you will find two options <strong>Insert Style</strong> and <strong>Insert Classic</strong> button to add it to your desired products.</p><p><img src="'+p+'" alt="CTA Link"></p><h3 id="feature-box" tabindex="-1">Feature Box <a class="header-anchor" href="#feature-box" aria-label="Permalink to &quot;Feature Box&quot;">​</a></h3><p>Feature Box doesn&#39;t have any customizable settings.</p><p><img src="'+g+'" alt="Feature Box"></p><p>Here, is the <strong>preview</strong> of the post where the selected <strong>Amazon Product</strong> whose <strong>elements</strong> are <strong>customized</strong> using the <strong>Product Elements</strong> feature.</p><p><img src="'+u+'" alt="Preview of customized elements of a specific product"></p><p>If you have any further questions, concerns, or suggestions, please do not hesitate to contact our support team. Thank you.</p><hr>',39)])])}const x=e(h,[["render",m]]);export{_ as __pageData,x as default};
